use serde_json::{json,Value};use sha2::{Sha256,Digest};use std::{fs,path::Path,collections::BTreeMap,process::Command,fmt::Write};
use rustc_demangle::demangle;
const R:&str="/home/ubuntu/src/zopro-perf-work/swiss-control-audit175";
const P:&str="/home/ubuntu/src/zopro-perf-work/swiss-groups-sdk175";
fn hash(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
#[derive(Clone)]struct Symbol{raw:String,pretty:String,address:u64,size:u64,bytes:Vec<u8>}
fn u16at(b:&[u8],i:usize)->u16{u16::from_le_bytes(b[i..i+2].try_into().unwrap())}
fn u64at(b:&[u8],i:usize)->u64{u64::from_le_bytes(b[i..i+8].try_into().unwrap())}
fn symbols(path:&str)->BTreeMap<String,Vec<Symbol>>{let bytes=fs::read(path).unwrap();assert_eq!(&bytes[..6],b"\x7fELF\x02\x01");assert_eq!(u16at(&bytes,18),62);let shoff=u64at(&bytes,40)as usize;let step=u16at(&bytes,58)as usize;assert_eq!(step,64);let count=u16at(&bytes,60)as usize;let mut exec=vec![];for n in 0..count{let at=shoff+n*step;let flags=u64at(&bytes,at+8);if flags&4!=0{exec.push((u64at(&bytes,at+16),u64at(&bytes,at+24),u64at(&bytes,at+32)));}}
let nm=Command::new("nm").args(["-S","--defined-only",path]).output().unwrap();assert!(nm.status.success());let mut out=BTreeMap::<String,Vec<Symbol>>::new();for line in String::from_utf8(nm.stdout).unwrap().lines(){let f=line.split_whitespace().collect::<Vec<_>>();if f.len()!=4||!["t","T","w","W"].contains(&f[2]){continue;}let address=u64::from_str_radix(f[0],16).unwrap();let size=u64::from_str_radix(f[1],16).unwrap();if size==0{continue;}let Some(&(addr,off,_))=exec.iter().find(|&&(addr,_,sz)|address>=addr&&address.checked_add(size).unwrap()<=addr+sz)else{continue};let start=(off+address-addr)as usize;let raw=f[3].to_string();let pretty=format!("{:#}",demangle(&raw));out.entry(pretty.clone()).or_default().push(Symbol{raw,pretty,address,size,bytes:bytes[start..start+size as usize].to_vec()});}out}
fn class(s:&str)->&'static str{if s.contains("g2_borrowed::apply"){"G2_stream"}else if s.contains("stream_g1_impl"){"G1_stream"}else if s.contains("msm_affine::grouping::scalar_groups"){"grouping"}else if s.contains("reduce_layer")&&s.contains("G2Config"){"G2_tree"}else if s.contains("reduce_layer")&&s.contains("G1Config"){"G1_tree"}else if s.contains("inverse::inverse")&&s.contains("FqConfig"){"Fq_inverse"}else{"other"}}
fn main(){let ids=read(format!("{P}/identities.json"));let a=symbols(ids["accepted"]["binary"].as_str().unwrap());let b=symbols(ids["OFF"]["binary"].as_str().unwrap());let mut rows=vec![];for(name,sa)in&a{if sa.len()!=1{continue;}let Some(sb)=b.get(name).filter(|v|v.len()==1)else{continue};let(sa,sb)=(&sa[0],&sb[0]);if sa.bytes==sb.bytes{continue;}let offsets=if sa.size==sb.size{Some(sa.bytes.iter().zip(&sb.bytes).enumerate().filter(|(_, (a,b))|a!=b).map(|(i,_)|i).collect::<Vec<_>>())}else{None};rows.push(json!({"name":name,"accepted_size":sa.size,"OFF_size":sb.size,"same_address":sa.address==sb.address,"differing_byte_offsets":offsets,"accepted_sha256":hash(&sa.bytes),"OFF_sha256":hash(&sb.bytes)}));}assert_eq!(rows.len(),67);fs::write(format!("{R}/differences.json"),serde_json::to_vec_pretty(&json!({"different_common_functions":rows,"count":67,"new_captures":0})).unwrap()).unwrap();for row in rows{println!("{} A={} OFF={} diffbytes={}",row["name"],row["accepted_size"],row["OFF_size"],row["differing_byte_offsets"].as_array().map(Vec::len).unwrap_or(usize::MAX));}}
